package com.example.Wishlist.Database;


import jakarta.persistence.*;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.Set;


// JPA Entity representing a user account in the USERS table
@Table(name="USERS")
@Entity
public class UserDB {

    // Primary key - auto-generated unique identifier for the user
    @Id
    @GeneratedValue(strategy = GenerationType.AUTO)
    @Column(name = "userId")
    private int userId;

    // Unique username for login
    @Size(min = 3, max = 50, message = "Username must be longer than 3 and less than 50 characters")
    @Column(name = "username")
    private String username;

    // User's password (NOTE: should be hashed in production)
    @Column(name = "password")
    private String password;

    // Role to distinguish between Admin and regular User
    @Column(name = "role")
    private String role;

    // Constructor to create a new user (userId will be auto-generated by database)
    public UserDB(String username, String password, String role) {
        this.username = username;
        this.password = password;
        this.role = role;
    }

    // Default constructor required by JPA/Hibernate
    public UserDB() {
    }
    
    // Getter for user ID
    public int getUserId() {
        return userId;
    }

    // Getter for username
    public String getUsername() {
        return username;
    }

    // Setter for username
    public void setUsername(String username) {
        this.username = username;
    }

    // Getter for password
    public String getPassword() {
        return password;
    }

    // Setter for password
    public void setPassword(String password) {
        this.password = password;
    }

    public String getRole(){
        return role;
    }

    public void setRole(String role){
        this.role = role;
    }
}

